import{_ as a,o as t,c as i,a2 as n}from"./chunks/framework.Ky-Ipuyb.js";const u=JSON.parse('{"title":"ImGui guide","description":"","frontmatter":{"lang":"en","sourcePath":"docs/imgui/README.md"},"headers":[],"relativePath":"imgui/index.md","filePath":"imgui/index.md"}'),s={name:"imgui/index.md"};function r(o,e,d,l,c,p){return t(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="imgui-guide" tabindex="-1">ImGui guide <a class="header-anchor" href="#imgui-guide" aria-label="Permalink to &quot;ImGui guide&quot;">​</a></h1><p>Use <code>sfml.js-imgui</code> to build debug panels, scene inspectors and native editor controls in an SFML window. The guides take you from the first frame loop to a tool with editable state, tables, text input, fonts and custom rendering.</p><p>The current sources target Dear ImGui 1.91.9b and imgui-sfml 3.0. Examples use JavaScript and the SFML 3.1 API. Start with basic JavaScript and the <a href="/guide/window">SFML window guide</a>; C++ knowledge is not required.</p><h2 id="follow-the-learning-path" tabindex="-1">Follow the learning path <a class="header-anchor" href="#follow-the-learning-path" aria-label="Permalink to &quot;Follow the learning path&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Chapter</th><th>What you will build or learn</th></tr></thead><tbody><tr><td><a href="/imgui/getting-started">Quick start</a></td><td>A complete counter, the frame lifecycle, input capture and safe shutdown</td></tr><tr><td><a href="/imgui/widgets">Widgets and state</a></td><td>Persistent editable values, unique IDs and a live scene inspector</td></tr><tr><td><a href="/imgui/layout">Layout and tool panels</a></td><td>A table, a menu, a confirmation modal and correct scope pairing</td></tr><tr><td><a href="/imgui/callbacks">Text input and callbacks</a></td><td>UTF-8 editing, callback contracts, list getters and plots</td></tr><tr><td><a href="/imgui/fonts">Fonts and style</a></td><td>Font atlas loading, CJK coverage, spacing, colors and DPI considerations</td></tr><tr><td><a href="/imgui/rendering">Rendering and multiple windows</a></td><td>Scene/UI composition, draw lists and per-window resource ownership</td></tr><tr><td><a href="/imgui/api">API guide</a></td><td>How to find exact signatures, overloads and lifetime contracts</td></tr></tbody></table><p>Each practical chapter links a complete runnable source, explains where its smaller snippets belong and describes what to expect. All chapters are maintained in English, Chinese, Japanese and Korean.</p><h2 id="choose-a-runnable-example" tabindex="-1">Choose a runnable example <a class="header-anchor" href="#choose-a-runnable-example" aria-label="Permalink to &quot;Choose a runnable example&quot;">​</a></h2><p>From the monorepo root, run bootstrap once, then launch an example:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/bootstrap.cjs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packages/sfml.js-imgui/examples/demo.cjs</span></span></code></pre></div><ul><li><a href="/examples/imgui#demo">Widget demo</a>: explore Dear ImGui&#39;s built-in widget and layout catalogue.</li><li><a href="/examples/imgui#scene-inspector">Scene inspector</a>: change a moving SFML circle&#39;s size, color and speed.</li><li><a href="/examples/imgui#workbench">Workbench</a>: combine text editing, object selection, a table, a modal and a timing plot.</li></ul><h2 id="understand-the-package-boundary" tabindex="-1">Understand the package boundary <a class="header-anchor" href="#understand-the-package-boundary" aria-label="Permalink to &quot;Understand the package boundary&quot;">​</a></h2><p><code>ImGui</code> exports the controls, enums, callback wrappers and native-handle operations. <code>SFML</code> integrates a native window, forwards its events and submits frames. Helpers such as <code>getFontAtlas</code> and <code>getStyleColors</code> are top-level exports.</p><p>Application values live in JavaScript; writable native scalar arguments use typed arrays. IO/style views, fonts and draw lists have native owners and limited lifetimes. The guides explain this boundary where each feature needs it; use the <a href="/reference/imgui/" target="_self">API reference</a> for the exact contract.</p>`,13)])])}const m=a(s,[["render",r]]);export{u as __pageData,m as default};
